/* Const lookup tables generated by tools/gen_tables.py into
 * src/core/eh_tables.c. Const data lives in flash on a device and costs no
 * SRAM; regenerate rather than hand-editing. */
#ifndef EH_TABLES_H
#define EH_TABLES_H

#include <stdint.h>

#include "eh_types.h"

#define EH_PALETTE_COUNT 4
#define EH_LED_SAMPLES 9

/* round(127.5 + 127.5 * sin(2*pi*i/256)) */
extern const uint8_t eh_sin8[256];

/* Visible span of each framebuffer row on the round display: pixel (x, y) is
 * visible iff eh_span_x0[y] <= x < eh_span_x1[y], i.e. its centre is within
 * radius 180 of the panel centre (the presentation mask, 1:1 at native
 * resolution). Renderers that clip to these spans write every pixel the
 * display shows. */
extern const uint16_t eh_span_x0[EH_FB_H];
extern const uint16_t eh_span_x1[EH_FB_H];

/* Cyclic 256-entry palettes; entry 255 blends back into entry 0. */
extern const eh_rgb565 eh_palettes[EH_PALETTE_COUNT][256];

/* Framebuffer pixel indices averaged for each LED: a 3x3 patch of
 * (radius, angle) samples near the rim at the LED's angular position. */
extern const uint32_t eh_led_samples[EH_LED_COUNT][EH_LED_SAMPLES];

#endif
